"""Generate mcsm/_bf_tables.py from a Blowfish bf_tab.h header.

Usage: python tools/gen_bf_tables.py path/to/bf_tab.h
The tables are the standard Blowfish P/S boxes (hex digits of pi), so any
correct bf_tab.h produces the same output. Kept for provenance.
"""
import re
import sys
from pathlib import Path

src = Path(sys.argv[1]).read_text()
out = [
    "# SPDX-License-Identifier: MIT",
    '"""Standard Blowfish P/S boxes. Generated by tools/gen_bf_tables.py."""',
    "",
]
for name in ("bfp", "ks0", "ks1", "ks2", "ks3"):
    body = re.search(rf"{name}\[\]\s*=\s*\{{(.*?)\}};", src, re.S).group(1)
    values = [int(v, 16) for v in re.findall(r"0x([0-9a-fA-F]{8})", body)]
    out.append(f"{name.upper()} = (")
    for i in range(0, len(values), 6):
        out.append("    " + " ".join(f"0x{v:08x}," for v in values[i:i + 6]))
    out.append(")")
    out.append("")

Path("mcsm/_bf_tables.py").write_text("\n".join(out))
print("wrote mcsm/_bf_tables.py")
